  // Month encodes the century: +0 for 1900s, +20 for 1800s, +40 for 2000s,
  // +60 for 2100s, +80 for 2200s.
  const centuryBases = [1900, 1800, 2000, 2100, 2200];
  const centuryIndex = Math.floor(mm / 20);
  const month = mm % 20;

  if (centuryIndex < 0 || centuryIndex >= centuryBases.length) {
    return false;
  }
  if (month < 1 || month > 12) {
    return false;
  }

  const year = centuryBases[centuryIndex] + yy;
  const isLeap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

  if (dd < 1 || dd > daysInMonth[month - 1]) {
    return false;
  }

  // Checksum: weighted sum of the first 9 digits, mod 11; 10 maps to 0.
  const weights = [2, 4, 8, 5, 10, 9, 7, 3, 6];
  let sum = 0;
  for (let i = 0; i < 9; i++) {
    sum += d[i] * weights[i];
  }
  let check = sum % 11;
  if (check === 10) {
    check = 0;
  }

  return check === d[9];
}

declare const lib: {
  minSatisfying(versions: string[], range: string, options?: unknown): string | null;
};

export function solve(versions: string[], range: string): string | null {
  return lib.minSatisfying(versions, range);
}

export function solve(id: string): boolean {
  // Remove slashes and backslashes
  const s = id.replace(/[\/\\]/g, '');

  // Exactly 11 digits
  if (!/^[0-9]{11}$/.test(s)) return false;

  // First digit must not be 0
  if (s[0] === '0') return false;

  // Repetition rule on the first 10 digits:
  // no digit may occur more than 3 times, and exactly one digit
  // must occur 2 or 3 times.
  const counts: number[] = new Array(10).fill(0);
  for (let i = 0; i < 10; i++) {
    counts[Number(s[i])]++;
  }
  let repeated = 0;
  for (const c of counts) {
    if (c > 3) return false;
    if (c >= 2) repeated++;
  }
  if (repeated !== 1) return false;

  // Check digit
  return lib.verhoeffCheck(s);
}
